mapper.select:
SELECT A.SEQNO seqno, A.VOUCH_YEAR vouchYear, A.VOUCH_QUARTER vouchQuarter, A.OPTIMISTIC_FACTOR optimisticFactor, A.BASIC_FACTOR basicFactor, A.PESSIMISM_FACTOR pessimismFactor FROM MOD_PD_FACTOR_CONFIG A WHERE 1=1
AND A.VOUCH_YEAR = #{vouchYear,jdbcType=VARCHAR}
AND A.VOUCH_QUARTER = #{vouchQuarter,jdbcType=VARCHAR}
ORDER BY A.VOUCH_YEAR DESC,A.VOUCH_QUARTER DESC
